import React, { useMemo, useState } from "react";
import { useDataStateContext } from "../context/DataStateContext";
import { Chart as ChartJS } from "chart.js";
import {
  Box,
  MenuItem,
  Select,
  Slider,
  ToggleButton,
  ToggleButtonGroup,
  Paper,
  Grid,
  Button,
  CircularProgress,
} from "@mui/material";
import { motion } from "framer-motion";
import ReceiptLongRoundedIcon from "@mui/icons-material/ReceiptLongRounded";
import PaidRoundedIcon from "@mui/icons-material/PaidRounded";
import { useAnimatedNumber } from "../Utils/useAnimatedNumber";
import { tokens } from "../../theme";
import { useThemeSwitcher } from "../../context/ThemeSwitcherContext";
import CategoryRaceBars from "./charts/CategoryRaceBars";
import RadarSpendProfile from "./charts/RadarSpendProfile";
import PolarPaymentMix from "./charts/PolarPaymentMix";
import SpendBubbleField from "./charts/SpendBubbleField";
import StackedCategoryTrend from "./charts/StackedCategoryTrend";
import SpendHeatmapCalendar from "./charts/SpendHeatmapCalendar";
import BudgetGaugeRadial from "./charts/BudgetGaugeRadial";
import "./analytics.scss";

// Chart.js defaults to dark text/gridlines, invisible on some of this app's
// themes — repoint the global defaults from the active theme's tokens.
// Re-applied on every render (cheap) rather than once at module load, so a
// theme switch is reflected immediately instead of only on next page load.
const applyChartDefaults = () => {
  ChartJS.defaults.color = tokens.textMuted;
  ChartJS.defaults.borderColor = tokens.gridLine;
  ChartJS.defaults.font.family = "Inter, sans-serif";
  ChartJS.defaults.plugins.tooltip.backgroundColor = tokens.bgDeep;
  ChartJS.defaults.plugins.tooltip.titleColor = tokens.textPrimary;
  ChartJS.defaults.plugins.tooltip.bodyColor = tokens.textPrimary;
  ChartJS.defaults.plugins.tooltip.borderColor = `${tokens.violet}73`;
  ChartJS.defaults.plugins.tooltip.borderWidth = 1;
  ChartJS.defaults.plugins.tooltip.padding = 10;
  ChartJS.defaults.plugins.tooltip.cornerRadius = 10;
  ChartJS.defaults.plugins.legend.labels.usePointStyle = true;
  ChartJS.defaults.plugins.legend.labels.boxWidth = 8;
  ChartJS.defaults.plugins.legend.labels.boxHeight = 8;
  ChartJS.defaults.plugins.legend.labels.padding = 12;
  ChartJS.defaults.plugins.legend.labels.font = { size: 11 };
};

// 0 means "All" (no lower bound) — included so charts don't render empty on
// first load when the data predates the old 30-day default window.
const rangeOptions = [0, 7, 30, 90, 365];

// Formats any day count into a compact label: plain days under a year, whole
// years when they land exactly on one, otherwise a rounded month count (or a
// decimal year for long spans that don't round cleanly to whole months).
const rangeLabel = (r: number): string => {
  if (r === 0) return "All";
  if (r < 365) return `${r}d`;
  const years = r / 365;
  if (Number.isInteger(years)) return `${years}y`;
  const months = Math.round(r / 30.44);
  return months < 24 ? `${months}mo` : `${years.toFixed(1)}y`;
};

// Extended-range slider marks, for dialing in something older than the
// farthest ToggleButtonGroup option (1y) without offering unbounded granularity.
const extendedRangeSteps = [365, 548, 730, 1095, 1460, 1825];
const extendedRangeMarks = extendedRangeSteps.map((r) => ({
  value: r,
  label: rangeLabel(r),
}));
const EXTENDED_RANGE_MIN = extendedRangeSteps[0];
const EXTENDED_RANGE_MAX = extendedRangeSteps[extendedRangeSteps.length - 1];

const Analytics: React.FC = () => {
  applyChartDefaults();
  const { theme } = useThemeSwitcher();
  const { state } = useDataStateContext();
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [range, setRange] = useState<number>(0);
  const [version, setVersion] = useState<number>(0);

  const items = state?.items || [];
  const categories = state?.category || [];
  const isLoading = !!(state?.loading?.items || state?.loading?.category);

  // Filtered items by selected category and date range. Every chart below
  // reads from this and shows its own "no data" state when the filter is
  // genuinely empty, instead of silently falling back to unfiltered data.
  const filteredItems = useMemo(() => {
    const minDate = Date.now() - range * 24 * 60 * 60 * 1000;
    return items.filter((it) => {
      const withinCategory =
        selectedCategory === "all" || it.category === selectedCategory;
      const withinRange = range === 0 || new Date(it.date).getTime() >= minDate;
      return withinCategory && withinRange;
    });
  }, [items, selectedCategory, range, version]);

  const totalAmount = filteredItems.reduce(
    (s, it) => s + parseFloat(String(it.price || 0)),
    0,
  );

  const animatedCount = useAnimatedNumber(filteredItems.length);
  const animatedAmount = useAnimatedNumber(totalAmount);

  // Automatically bump version when item ids change so charts refresh
  React.useEffect(() => {
    const ids = (items || []).map((i) => i?.id).join(",");
    setVersion((v) => v + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items.length]);

  const chartCards = [
    <CategoryRaceBars items={filteredItems} categories={categories} />,
    <RadarSpendProfile items={filteredItems} categories={categories} />,
    <PolarPaymentMix items={filteredItems} categories={categories} />,
    <SpendBubbleField items={filteredItems} categories={categories} />,
    <BudgetGaugeRadial items={filteredItems} categories={categories} />,
  ];

  const featureCards = [
    <StackedCategoryTrend items={filteredItems} categories={categories} />,
    <SpendHeatmapCalendar items={filteredItems} categories={categories} />,
  ];

  return (
    <div className="analytics-root">
      <Box mb={2}>
        <Grid container spacing={2} alignItems="stretch">
          <Grid item xs={12} md={4}>
            <motion.div
              className="stat-tile stat-tile--violet"
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3 }}
            >
              <ReceiptLongRoundedIcon className="stat-tile-icon" />
              <span className="stat-tile-label">Total Items</span>
              <span className="stat-tile-value mono">
                {Math.round(animatedCount)}
              </span>
            </motion.div>
          </Grid>
          <Grid item xs={12} md={4}>
            <motion.div
              className="stat-tile stat-tile--amber"
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: 0.05 }}
            >
              <PaidRoundedIcon className="stat-tile-icon" />
              <span className="stat-tile-label">Total Amount</span>
              <span className="stat-tile-value mono">
                ₹ {animatedAmount.toLocaleString("en-IN", { maximumFractionDigits: 0 })}
              </span>
            </motion.div>
          </Grid>
          <Grid item xs={12} md={4}>
            <Paper className="stat-card controls">
              <Box className="controls-row">
                <Select
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(String(e.target.value))}
                  size="small"
                >
                  <MenuItem value="all">All categories</MenuItem>
                  {categories.map((c) => (
                    <MenuItem key={c.id} value={c.id}>
                      {c.name}
                    </MenuItem>
                  ))}
                </Select>
                <ToggleButtonGroup
                  value={range}
                  exclusive
                  onChange={(e, v) => v !== null && setRange(v)}
                  size="small"
                  className="range-toggle"
                >
                  {rangeOptions.map((r) => (
                    <ToggleButton key={r} value={r} aria-label={rangeLabel(r)}>
                      {rangeLabel(r)}
                    </ToggleButton>
                  ))}
                </ToggleButtonGroup>
                <Button
                  size="small"
                  onClick={() => {
                    setSelectedCategory("all");
                    setRange(0);
                  }}
                >
                  Reset
                </Button>
                <Button
                  size="small"
                  variant="contained"
                  onClick={() => setVersion((v) => v + 1)}
                  style={{ marginLeft: 8 }}
                >
                  Refresh
                </Button>
              </Box>
              <Box className="controls-row controls-row--extended">
                <span className="controls-extended-label">Older than 1y</span>
                <Slider
                  size="small"
                  className="extended-range-slider"
                  value={Math.min(
                    Math.max(range, EXTENDED_RANGE_MIN),
                    EXTENDED_RANGE_MAX,
                  )}
                  onChange={(e, v) => setRange(v as number)}
                  min={EXTENDED_RANGE_MIN}
                  max={EXTENDED_RANGE_MAX}
                  step={null}
                  marks={extendedRangeMarks}
                  valueLabelDisplay="auto"
                  valueLabelFormat={rangeLabel}
                  color="primary"
                />
              </Box>
            </Paper>
          </Grid>
        </Grid>
      </Box>

      <Grid container spacing={2}>
        {chartCards.map((node, i) => (
          <Grid item xs={12} md={6} key={`${i}-${theme.key}`}>
            <motion.div
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: 0.05 * i }}
              whileHover={{ y: -3 }}
            >
              <Paper className="chart-card">
                {isLoading ? (
                  <Box display="flex" justifyContent="center" p={4}>
                    <CircularProgress size={28} />
                  </Box>
                ) : (
                  node
                )}
              </Paper>
            </motion.div>
          </Grid>
        ))}

        {featureCards.map((node, i) => (
          <Grid item xs={12} key={`${i}-${theme.key}`}>
            <motion.div
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: 0.25 + 0.05 * i }}
            >
              <Paper className="chart-card">
                {isLoading ? (
                  <Box display="flex" justifyContent="center" p={4}>
                    <CircularProgress size={28} />
                  </Box>
                ) : (
                  node
                )}
              </Paper>
            </motion.div>
          </Grid>
        ))}
      </Grid>
    </div>
  );
};

export default Analytics;
