declare global {
  interface Window {
    google?: any;
  }
}

const CLIENT_ID = process.env.REACT_APP_GOOGLE_DRIVE_CLIENT_ID;
const SCOPE = "https://www.googleapis.com/auth/drive.file";

let tokenClient: any = null;
let cachedToken: { token: string; expiresAt: number } | null = null;

const initTokenClient = (): any => {
  if (!window.google?.accounts?.oauth2) {
    throw new Error(
      "Google Identity Services hasn't loaded yet — check your connection and reload."
    );
  }
  if (!CLIENT_ID) {
    throw new Error(
      "Missing REACT_APP_GOOGLE_DRIVE_CLIENT_ID — set it in .env.local and restart the dev server."
    );
  }
  if (!tokenClient) {
    tokenClient = window.google.accounts.oauth2.initTokenClient({
      client_id: CLIENT_ID,
      scope: SCOPE,
      callback: () => {},
    });
  }
  return tokenClient;
};

// requestAccessToken() shows the Google consent popup only the first time in
// a browser session — after that it silently renews as long as the session
// is still valid, so callers don't need to think about this.
export const getAccessToken = (): Promise<string> => {
  if (cachedToken && cachedToken.expiresAt > Date.now() + 30_000) {
    return Promise.resolve(cachedToken.token);
  }

  const client = initTokenClient();
  return new Promise((resolve, reject) => {
    client.callback = (resp: any) => {
      if (resp.error) {
        reject(new Error(resp.error));
        return;
      }
      cachedToken = {
        token: resp.access_token,
        expiresAt: Date.now() + (resp.expires_in ?? 3600) * 1000,
      };
      resolve(resp.access_token);
    };
    client.requestAccessToken({ prompt: "" });
  });
};

export const uploadReceiptToDrive = async (
  file: File
): Promise<{ fileId: string; viewUrl: string }> => {
  const token = await getAccessToken();
  const boundary = `dream_${Math.random().toString(36).slice(2)}`;
  const metadata = JSON.stringify({
    name: file.name,
    mimeType: file.type || "application/octet-stream",
  });

  const body = new Blob([
    `--${boundary}\r\n`,
    `Content-Type: application/json; charset=UTF-8\r\n\r\n`,
    metadata,
    `\r\n--${boundary}\r\n`,
    `Content-Type: ${file.type || "application/octet-stream"}\r\n\r\n`,
    file,
    `\r\n--${boundary}--`,
  ]);

  const uploadRes = await fetch(
    "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id",
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": `multipart/related; boundary=${boundary}`,
      },
      body,
    }
  );
  if (!uploadRes.ok) {
    throw new Error(`Drive upload failed: ${uploadRes.status} ${await uploadRes.text()}`);
  }
  const { id: fileId } = await uploadRes.json();

  const permRes = await fetch(
    `https://www.googleapis.com/drive/v3/files/${fileId}/permissions`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ role: "reader", type: "anyone" }),
    }
  );
  if (!permRes.ok) {
    throw new Error(
      `Drive sharing failed: ${permRes.status} ${await permRes.text()}`
    );
  }

  return {
    fileId,
    viewUrl: `https://drive.google.com/thumbnail?id=${fileId}&sz=w2000`,
  };
};

// Best-effort — an already-missing file (or a permissions hiccup) shouldn't
// block the caller's own success path.
export const deleteReceiptFromDrive = async (fileId: string): Promise<void> => {
  try {
    const token = await getAccessToken();
    await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });
  } catch (e) {
    console.log(e);
  }
};
