export interface FirebaseConfig {
  apiKey: string;
  authDomain: string;
  projectId: string;
  storageBucket: string;
  messagingSenderId: string;
  appId: string;
  measurementId: string;
}

export interface AuthSlot {
  defaultValue: number;
  valid: number;
}

export interface UserConfig {
  label: string;
  // Sourced from Firestore (AppUsers collection in SHARED_PROJECT_KEY's
  // project) at runtime via useAppUsers — see src/config/useAppUsers.ts.
  // Optional here only because this static entry has no local fallback.
  authSlots?: AuthSlot[];
  // Omit `firebase` for a new user: they'll automatically share the
  // SHARED_PROJECT_KEY user's Firebase project instead of needing their own,
  // with their Firestore docs tagged by a `userId` field for isolation.
  firebase?: FirebaseConfig;
}

// The user whose Firebase project every "firebase"-less user shares, and
// where the AppUsers directory (labels + pins for every user) lives.
export const SHARED_PROJECT_KEY = "manish";

