import React, { useMemo } from "react";
import { Chart as ChartJS, RadialLinearScale, ArcElement, Tooltip, Legend } from "chart.js";
import { PolarArea } from "react-chartjs-2";
import { Box, Typography } from "@mui/material";
import { tokens } from "../../../theme";
import { IItems, ICategoryProps } from "../../context/DataStateModels";

ChartJS.register(RadialLinearScale, ArcElement, Tooltip, Legend);

const formatCurrency = (value: number) => `₹${Math.round(value).toLocaleString("en-IN")}`;

type PolarPaymentMixProps = {
  items: IItems[];
  categories: ICategoryProps[];
};

const PolarPaymentMix: React.FC<PolarPaymentMixProps> = ({ items }) => {
  const { labels, amounts, total } = useMemo(() => {
    const totals = new Map<string, number>();

    items.forEach((item) => {
      const mode = item.pmode?.trim() || "Unknown";
      const price = parseFloat(String(item.price)) || 0;
      totals.set(mode, (totals.get(mode) || 0) + price);
    });

    const sorted = Array.from(totals.entries()).sort((a, b) => b[1] - a[1]);

    return {
      labels: sorted.map(([mode]) => mode),
      amounts: sorted.map(([, amount]) => amount),
      total: sorted.reduce((sum, [, amount]) => sum + amount, 0),
    };
  }, [items]);

  const hasData = labels.length > 0 && total > 0;

  const paymentPalette = [
    tokens.violet,
    tokens.cyan,
    tokens.amber,
    tokens.emerald,
    tokens.rose,
    tokens.sky,
    tokens.fuchsia,
    tokens.lime,
  ];

  const data = {
    labels,
    datasets: [
      {
        data: amounts,
        backgroundColor: labels.map((_, i) => `${paymentPalette[i % paymentPalette.length]}cc`),
        borderColor: labels.map((_, i) => paymentPalette[i % paymentPalette.length]),
        borderWidth: 1.5,
      },
    ],
  };

  const options = {
    maintainAspectRatio: true,
    scales: {
      r: {
        ticks: { display: false },
        grid: { color: tokens.gridLine },
        angleLines: { color: tokens.gridLine },
      },
    },
    plugins: {
      legend: { position: "bottom" as const },
      tooltip: {
        callbacks: {
          label: (ctx: any) => {
            const value = ctx.raw as number;
            const pct = total > 0 ? ((value / total) * 100).toFixed(1) : "0.0";
            return `${ctx.label}: ${formatCurrency(value)} (${pct}%)`;
          },
        },
      },
    },
  };

  return (
    <>
      <Typography variant="subtitle1">Payment Mix</Typography>
      {hasData ? (
        <PolarArea data={data} options={options} />
      ) : (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            minHeight: 200,
          }}
        >
          <Typography variant="body2" color="text.secondary">
            No data yet
          </Typography>
        </Box>
      )}
    </>
  );
};

export default PolarPaymentMix;
