import { useDataStateContext } from "../context/DataStateContext";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
import {
  categoryDoc,
  categoryList,
  filterOwnDocs,
  getCategoryColor,
  scopedQuery,
  TModes,
} from "../Utils/Utils";
import "../Items/items.scss";
