import { doc, getDoc, setDoc } from "firebase/firestore";
import { getFirebaseServices } from "../Firebase/config";
import { SHARED_PROJECT_KEY } from "./userConfig";

// Gates the "add user" UI. Stored as a hash (not plaintext) in the shared
// project's Firestore, in the same doc every device checks against — so
// whoever sets it first becomes the only one who can add users afterwards.
const ADMIN_CONFIG_COLLECTION = "AppConfig";
const ADMIN_CONFIG_DOC = "admin";

const sha256Hex = async (text: string) => {
  const bytes = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
};

const getAdminDocRef = () => {
  const { db } = getFirebaseServices(SHARED_PROJECT_KEY);
  return doc(db, ADMIN_CONFIG_COLLECTION, ADMIN_CONFIG_DOC);
};

export const hasAdminPassword = async (): Promise<boolean> => {
  const snap = await getDoc(getAdminDocRef());
  return snap.exists() && !!snap.data()?.passwordHash;
};

export const setAdminPassword = async (password: string): Promise<void> => {
  const passwordHash = await sha256Hex(password);
  await setDoc(getAdminDocRef(), { passwordHash });
};

export const verifyAdminPassword = async (password: string): Promise<boolean> => {
  const snap = await getDoc(getAdminDocRef());
  const storedHash = snap.data()?.passwordHash;
  if (!storedHash) return false;
  return storedHash === (await sha256Hex(password));
};
