import { useMemo, useState } from "react";
import { addDoc } from "firebase/firestore";
import UploadIcon from "@mui/icons-material/Upload";
import { useDataStateContext } from "../context/DataStateContext";
import { useFireBase } from "../../context/FirebaseConfigContext";
import { getDataScopeUserId, getFirebaseServices } from "../../Firebase/config";
import { categoryList, itemList } from "../Utils/Utils";
import { ICategoryProps, IItems } from "../context/DataStateModels";
import {
  ImportGroup,
  RawImportRow,
  groupImportRowsByCategory,
  parseImportFile,
} from "./importExportUtils";

type Resolution = { mode: "existing" | "new"; newName?: string };

const ImportItemsPanel = ({ onClose }: { onClose: () => void }) => {
  const { state, dispatch } = useDataStateContext();
  const { state: firebaseState } = useFireBase();
  const db = getFirebaseServices(firebaseState.userId).db;
  const scopeUserId = getDataScopeUserId(firebaseState.userId);

  const [fileName, setFileName] = useState("");
  const [groups, setGroups] = useState<Map<string, ImportGroup> | null>(null);
  const [resolutions, setResolutions] = useState<Record<string, Resolution>>({});
  const [error, setError] = useState("");
  const [isImporting, setIsImporting] = useState(false);
  const [summary, setSummary] = useState<{
    categories: number;
    newCategories: number;
    items: number;
  } | null>(null);

  const existingByName = useMemo(
    () => new Map((state?.category || []).map((c) => [c.name.trim().toLowerCase(), c])),
    [state?.category]
  );

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setError("");
    setSummary(null);
    setFileName(file.name);
    try {
      const rows: RawImportRow[] = await parseImportFile(file);
      if (!rows.length) {
        setError("No items found in that file.");
        setGroups(null);
        return;
      }
      const grouped = groupImportRowsByCategory(rows);
      const initialResolutions: Record<string, Resolution> = {};
      grouped.forEach((_, catName) => {
        if (existingByName.has(catName.toLowerCase())) {
          initialResolutions[catName] = { mode: "existing" };
        }
      });
      setResolutions(initialResolutions);
      setGroups(grouped);
    } catch (err) {
      console.error(err);
      setError("Couldn't read that file — use a .json or .xlsx export from this app.");
      setGroups(null);
    }
  };

  const runImport = async () => {
    if (!groups) return;
    setIsImporting(true);
    setError("");
    try {
      const newCategories: ICategoryProps[] = [];
      const newItems: IItems[] = [];
      const categoryIdByGroupName = new Map<string, string>();

      for (const [catName, group] of Array.from(groups.entries())) {
        const match = existingByName.get(catName.toLowerCase());
        const resolution = resolutions[catName];

        if (match && (!resolution || resolution.mode === "existing")) {
          categoryIdByGroupName.set(catName, match.id as string);
          continue;
        }

        const newName =
          match && resolution?.mode === "new"
            ? resolution.newName?.trim() || `${catName} (imported)`
            : catName;

        // Only links to an *existing* parent category by name — a parent that
        // is itself new in this same file is imported as a top-level category
        // instead of chaining creation, to keep the import a single flat pass.
        const parentMatch = group.parentCategory
          ? state?.category?.find(
              (c) =>
                !c.parentId &&
                c.name.trim().toLowerCase() === group.parentCategory!.trim().toLowerCase()
            )
          : undefined;

        const payload: ICategoryProps = {
          name: newName,
          ...(parentMatch ? { parentId: parentMatch.id } : {}),
        };
        const docRef = await addDoc(
          categoryList(db),
          scopeUserId ? { ...payload, userId: scopeUserId } : payload
        );
        categoryIdByGroupName.set(catName, docRef.id);
        newCategories.push({ ...payload, id: docRef.id });
      }

      for (const [catName, group] of Array.from(groups.entries())) {
        const categoryId = categoryIdByGroupName.get(catName) as string;
        for (const row of group.items) {
          const payload: IItems = {
            name: row.name || "",
            price: row.price ?? "",
            description: row.description || "",
            category: categoryId,
            date: row.date || new Date().toISOString(),
            revisit: row.revisit === "Yes" ? "Yes" : "No",
            pmode: row.pmode || "Cash",
          };
          const docRef = await addDoc(
            itemList(db),
            scopeUserId ? { ...payload, userId: scopeUserId } : payload
          );
          newItems.push({ ...payload, id: docRef.id });
        }
      }

      dispatch({
        type: "addCategory",
        payload: [...(state?.category || []), ...newCategories],
      });
      dispatch({ type: "addItems", payload: [...(state?.items || []), ...newItems] });

      setSummary({
        categories: groups.size,
        newCategories: newCategories.length,
        items: newItems.length,
      });
      setGroups(null);
      setFileName("");
    } catch (err) {
      console.error(err);
      setError("Import failed — check the console for details.");
    } finally {
      setIsImporting(false);
    }
  };

  return (
    <div className="import-items-panel">
      <h3 className="import-items-title">Import items</h3>
      <p className="import-items-hint">
        Choose a .json or .xlsx file exported from the Category wise view. Items whose
        category already exists can be added to it, or filed under a new category instead.
      </p>

      <label className="receipt-upload-btn">
        <UploadIcon fontSize="small" />
        {fileName || "Choose file"}
        <input
          type="file"
          accept=".json,.xlsx,.xls"
          onChange={handleFile}
          style={{ display: "none" }}
        />
      </label>

      {error && <p className="import-error">{error}</p>}

      {groups && (
        <div className="import-groups">
          {Array.from(groups.entries()).map(([catName, group]) => {
            const match = existingByName.get(catName.toLowerCase());
            const resolution = resolutions[catName];
            return (
              <div className="import-group-row" key={catName}>
                <div className="import-group-head">
                  <span>{catName}</span>
                  <span className="import-group-count">
                    {group.items.length} item{group.items.length === 1 ? "" : "s"}
                  </span>
                </div>
                {match ? (
                  <div className="import-group-choice">
                    <label>
                      <input
                        type="radio"
                        name={`import-res-${catName}`}
                        checked={(resolution?.mode ?? "existing") === "existing"}
                        onChange={() =>
                          setResolutions((prev) => ({
                            ...prev,
                            [catName]: { mode: "existing" },
                          }))
                        }
                      />
                      Add to existing "{match.name}"
                    </label>
                    <label>
                      <input
                        type="radio"
                        name={`import-res-${catName}`}
                        checked={resolution?.mode === "new"}
                        onChange={() =>
                          setResolutions((prev) => ({
                            ...prev,
                            [catName]: {
                              mode: "new",
                              newName: prev[catName]?.newName || `${catName} (imported)`,
                            },
                          }))
                        }
                      />
                      Create a new category
                    </label>
                    {resolution?.mode === "new" && (
                      <input
                        type="text"
                        className="import-new-name-input"
                        value={resolution.newName || ""}
                        onChange={(e) =>
                          setResolutions((prev) => ({
                            ...prev,
                            [catName]: { mode: "new", newName: e.target.value },
                          }))
                        }
                      />
                    )}
                  </div>
                ) : (
                  <div className="import-group-choice import-group-choice--new">
                    Will create a new category "{catName}"
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {summary && (
        <p className="import-success">
          Imported {summary.items} item{summary.items === 1 ? "" : "s"} across{" "}
          {summary.categories} categor{summary.categories === 1 ? "y" : "ies"} (
          {summary.newCategories} new).
        </p>
      )}

      <div className="import-actions">
        <button
          type="button"
          className="add-item-btn"
          disabled={!groups || isImporting}
          onClick={runImport}
        >
          {isImporting ? "Importing…" : "Import"}
        </button>
        <button type="button" className="row-action-btn import-close-btn" onClick={onClose}>
          Close
        </button>
      </div>
    </div>
  );
};

export default ImportItemsPanel;
