import { SVGProps } from "react";

const Marigold = ({ cx, cy, r, color }: { cx: number; cy: number; r: number; color: string }) => (
  <g transform={`translate(${cx} ${cy})`} stroke={color} strokeLinecap="round">
    {Array.from({ length: 8 }).map((_, i) => {
      const angle = (i * 360) / 8;
      return <circle key={i} cx={0} cy={-r * 0.6} r={r * 0.4} transform={`rotate(${angle})`} strokeWidth={1} opacity={0.6} />;
    })}
    <circle r={r * 0.35} fill={color} stroke="none" opacity={0.8} />
  </g>
);

const MarigoldDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <path
      d="M14 30 C 40 44, 30 60, 56 66 S 78 90, 104 96 S 128 116, 146 110"
      stroke="var(--text-muted)"
      strokeWidth={1.2}
      strokeLinecap="round"
      opacity={0.4}
    />
    <Marigold cx={40} cy={40} r={9} color="var(--money)" />
    <Marigold cx={72} cy={70} r={7} color="var(--accent-1)" />
    <Marigold cx={104} cy={94} r={8} color="var(--money)" />
    <Marigold cx={132} cy={112} r={6} color="var(--accent-1)" />
  </svg>
);

export default MarigoldDoodle;
