import { useMemo } from "react";
import { getSeasonalDoodle } from "./getSeasonalDoodle";

const OccasionDoodle = () => {
  const doodle = useMemo(() => getSeasonalDoodle(new Date()), []);
  const { Component } = doodle;

  return (
    <div className="auth-doodle" aria-hidden="true" title={doodle.label}>
      <Component className="auth-doodle-svg" />
    </div>
  );
};

export default OccasionDoodle;
