import writeXlsxFile from "write-excel-file/browser";
import { readSheet } from "read-excel-file/browser";
import { ICategoryProps, IItems } from "../context/DataStateModels";

export type ExportRow = {
  category: string;
  parentCategory: string;
  name: string;
  price: number | string;
  date: string;
  description: string;
  revisit: string;
  pmode: string;
};

export const buildCategoryById = (categories: ICategoryProps[]) =>
  new Map(categories.map((cat) => [cat.id as string, cat]));

// Walks a "Category wise" tree node (see ItemsList#createCategoryWiseData) down
// to the raw IItems leaves — a node is a category/subcategory as long as it has
// a `children` array; anything without one is an actual item.
export const collectLeafItems = (node: any): IItems[] =>
  (node.children || []).flatMap((child: any) =>
    child.children ? collectLeafItems(child) : [child]
  );

export const toExportRows = (
  items: IItems[],
  categoryById: Map<string, ICategoryProps>
): ExportRow[] =>
  items.map((item) => {
    const cat = categoryById.get(item.category);
    const parentCat = cat?.parentId ? categoryById.get(cat.parentId) : undefined;
    return {
      category: cat?.name || "Uncategorized",
      parentCategory: parentCat?.name || "",
      name: item.name || "",
      price: item.price ?? "",
      date: item.date || "",
      description: item.description || "",
      revisit: item.revisit || "No",
      pmode: item.pmode || "",
    };
  });

export const sanitizeFileName = (name: string) =>
  (name || "category")
    .trim()
    .replace(/[^a-z0-9-_ ]/gi, "")
    .replace(/\s+/g, "-")
    .toLowerCase() || "category";

export const triggerJsonDownload = (rows: ExportRow[], filename: string) => {
  const blob = new Blob([JSON.stringify(rows, null, 2)], {
    type: "application/json",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
};

const XLSX_COLUMNS: { header: string; key: keyof ExportRow }[] = [
  { header: "Category", key: "category" },
  { header: "Parent Category", key: "parentCategory" },
  { header: "Name", key: "name" },
  { header: "Price", key: "price" },
  { header: "Date", key: "date" },
  { header: "Description", key: "description" },
  { header: "Revisit", key: "revisit" },
  { header: "Payment Mode", key: "pmode" },
];

export const triggerXlsxDownload = (rows: ExportRow[], filename: string) =>
  writeXlsxFile(rows, {
    columns: XLSX_COLUMNS.map(({ header, key }) => ({
      header,
      cell: (row: ExportRow) => row[key],
    })),
  }).toFile(filename);

// ---- Import parsing ----
// Both formats round-trip through the same flat shape as ExportRow (minus the
// blank-vs-missing distinction), so a file exported from one category button
// and a hand-merged file combining several are parsed identically.

export type RawImportRow = {
  category: string;
  parentCategory?: string;
  name: string;
  price: number | string;
  date: string;
  description?: string;
  revisit?: string;
  pmode?: string;
};

const XLSX_HEADER_MAP: Record<string, keyof RawImportRow> = {
  category: "category",
  "parent category": "parentCategory",
  name: "name",
  price: "price",
  date: "date",
  description: "description",
  revisit: "revisit",
  "payment mode": "pmode",
};

const parseXlsxImportFile = async (file: File): Promise<RawImportRow[]> => {
  const data = await readSheet(file);
  if (!data.length) return [];
  const headers = data[0].map((h) => String(h ?? "").trim().toLowerCase());
  return data
    .slice(1)
    .map((row) => {
      const obj: any = {};
      headers.forEach((header, i) => {
        const key = XLSX_HEADER_MAP[header];
        if (!key) return;
        let value: any = row[i];
        if (value instanceof Date) value = value.toISOString();
        obj[key] = value === null || value === undefined ? "" : value;
      });
      return obj as RawImportRow;
    })
    .filter((row) => row.name);
};

const parseJsonImportFile = async (file: File): Promise<RawImportRow[]> => {
  const data = JSON.parse(await file.text());
  if (!Array.isArray(data)) {
    throw new Error("Expected a JSON array of items");
  }
  return data;
};

export const parseImportFile = (file: File): Promise<RawImportRow[]> => {
  const ext = file.name.split(".").pop()?.toLowerCase();
  return ext === "json" ? parseJsonImportFile(file) : parseXlsxImportFile(file);
};

export type ImportGroup = { parentCategory?: string; items: RawImportRow[] };

export const groupImportRowsByCategory = (
  rows: RawImportRow[]
): Map<string, ImportGroup> => {
  const groups = new Map<string, ImportGroup>();
  rows.forEach((row) => {
    const catName = String(row.category || "Uncategorized").trim() || "Uncategorized";
    if (!groups.has(catName)) {
      groups.set(catName, {
        parentCategory: row.parentCategory
          ? String(row.parentCategory).trim() || undefined
          : undefined,
        items: [],
      });
    }
    groups.get(catName)!.items.push(row);
  });
  return groups;
};
