import { SVGProps } from "react";

const Heart = ({ cx, cy, s, color, opacity }: { cx: number; cy: number; s: number; color: string; opacity: number }) => (
  <path
    d={`M${cx} ${cy + s * 0.3}
        C ${cx - s} ${cy - s * 0.6}, ${cx - s * 0.4} ${cy - s * 1.3}, ${cx} ${cy - s * 0.55}
        C ${cx + s * 0.4} ${cy - s * 1.3}, ${cx + s} ${cy - s * 0.6}, ${cx} ${cy + s * 0.3} Z`}
    stroke={color}
    strokeWidth={1.6}
    strokeLinejoin="round"
    opacity={opacity}
  />
);

const ValentineDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <path
      d="M14 120 C 40 110, 48 88, 74 78"
      stroke="var(--accent-1)"
      strokeWidth={1.2}
      strokeLinecap="round"
      opacity={0.4}
    />
    <Heart cx={46} cy={54} s={22} color="var(--accent-1)" opacity={0.85} />
    <Heart cx={94} cy={86} s={14} color="var(--money)" opacity={0.7} />
    <Heart cx={110} cy={40} s={9} color="var(--accent-2)" opacity={0.55} />
  </svg>
);

export default ValentineDoodle;
