import { useEffect, useRef, useState } from "react";
import { ICategoryProps, IItems } from "../context/DataStateModels";
import { useDataStateContext } from "../context/DataStateContext";
import DeleteIcon from "@mui/icons-material/Delete";
import ImageNotSupportedRoundedIcon from "@mui/icons-material/ImageNotSupportedRounded";
import { deleteDoc, doc } from "firebase/firestore";

import { getFirebaseServices } from "../../Firebase/config";
import EditIcon from "@mui/icons-material/Edit";
import FileDownloadIcon from "@mui/icons-material/FileDownload";
import UploadFileIcon from "@mui/icons-material/UploadFile";
import { Menu, MenuItem } from "@mui/material";
import "./items.scss";
import { Modal } from "../Modal";
import { Badge, Table, Tree } from "@manish774/smarty-ui";
import { getCategoryColor, TModes } from "../Utils/Utils";
import { useFireBase } from "../../context/FirebaseConfigContext";
import Analytics from "../Analytics/Analytics";
import { motion } from "framer-motion";
import { useAnimatedNumber } from "../Utils/useAnimatedNumber";
import { tokens } from "../../theme";
import { useThemeSwitcher } from "../../context/ThemeSwitcherContext";
import ImportItemsPanel from "./ImportItemsPanel";
import {
  buildCategoryById,
  collectLeafItems,
  sanitizeFileName,
  toExportRows,
  triggerJsonDownload,
  triggerXlsxDownload,
} from "./importExportUtils";

// Module scope (not defined inside ItemsList) so it isn't recreated as a new
// component type on every ItemsList render, which would remount every cell
// and reset its expand/collapse state on unrelated re-renders (e.g. the
// total-price count-up animation).
const DESCRIPTION_TRUNCATE_LENGTH = 40;
// Must match the "row-scrap" keyframe animation duration in items.scss
const ROW_SCRAP_DURATION_MS = 700;

const DescriptionCell = ({ text }: { text?: string }) => {
  const [expanded, setExpanded] = useState(false);
  const value = text || "";

  if (value.length <= DESCRIPTION_TRUNCATE_LENGTH) {
    return <span className="description-cell">{value}</span>;
  }

  if (expanded) {
    return (
      <span className="description-cell">
        {value}
        <button
          type="button"
          className="description-toggle"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            setExpanded(false);
          }}
        >
          Show less
        </button>
      </span>
    );
  }

  return (
    <span className="description-cell description-cell--collapsed">
      <span className="description-cell-text">{value}</span>
      <button
        type="button"
        className="description-toggle"
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          setExpanded(true);
        }}
      >
        Show more
      </button>
    </span>
  );
};

// Export control for one category row in the "Category wise" tree — flattens
// that node's items (including any subcategories) and offers JSON or Excel.
const CategoryExportButton = ({
  node,
  categoryById,
}: {
  node: any;
  categoryById: Map<string, ICategoryProps>;
}) => {
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [isExporting, setIsExporting] = useState(false);
  const items = collectLeafItems(node);

  const closeMenu = () => setAnchorEl(null);

  const handleExportJson = (e: React.MouseEvent) => {
    e.stopPropagation();
    triggerJsonDownload(toExportRows(items, categoryById), `${sanitizeFileName(node.name)}.json`);
    closeMenu();
  };

  const handleExportXlsx = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsExporting(true);
    try {
      await triggerXlsxDownload(
        toExportRows(items, categoryById),
        `${sanitizeFileName(node.name)}.xlsx`
      );
    } catch (err) {
      console.error(err);
    } finally {
      setIsExporting(false);
      closeMenu();
    }
  };

  return (
    <>
      <button
        type="button"
        className="row-action-btn"
        aria-label={`Export ${node.name} category`}
        disabled={!items.length || isExporting}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          setAnchorEl(e.currentTarget);
        }}
      >
        <FileDownloadIcon className="row-action-icon" fontSize="small" />
      </button>
      <Menu
        anchorEl={anchorEl}
        open={!!anchorEl}
        onClose={closeMenu}
        onClick={(e) => e.stopPropagation()}
      >
        <MenuItem onClick={handleExportJson}>Export as JSON</MenuItem>
        <MenuItem onClick={handleExportXlsx}>Export as Excel</MenuItem>
      </Menu>
    </>
  );
};

const ItemsList = ({
  handleMode,
}: {
  handleMode: (newMode: TModes, id: string) => any;
}) => {
  const { state, dispatch } = useDataStateContext();
  const { themeKey } = useThemeSwitcher();
  const [totalPrice, setTotalPrice] = useState<number>(0);
  const [categoryData, setCategoryData] = useState<IItems[]>([]); // State to hold category-wise data
  const [selectedIdToDelete, setSelectedIdToDelete] = useState<string>("");
  const [isDialogOpen, setIsDialogOpen] = useState<boolean>(false);
  const [previewImageUrl, setPreviewImageUrl] = useState<string>("");
  const [isImportOpen, setIsImportOpen] = useState<boolean>(false);
  const rowToDeleteRef = useRef<HTMLTableRowElement | null>(null);
  const isItemsLoading = state?.loading?.items;
  const { state: firebaseState } = useFireBase();
  const animatedTotal = useAnimatedNumber(totalPrice);

  useEffect(() => {
    const calculatePrice = state?.items?.reduce(
      (acc, curr) => acc + parseFloat(String(curr.price) || "0"),
      0
    );
    setTotalPrice(calculatePrice);
  }, [state]);

  useEffect(() => {
    //For category wise
    if (state.items) {
      const categoryWiseData = createCategoryWiseData(state?.items);
      setCategoryData(categoryWiseData);
    }
  }, [state.items]);

  const formatDate = (date: string) =>
    new Date(date).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });

  const deleteItem = async () => {
    const itemDoc = doc(
      getFirebaseServices(firebaseState.userId).db,
      "Items",
      selectedIdToDelete
    );
    await deleteDoc(itemDoc);
    dispatch({
      type: "addItems",
      payload: state?.items?.filter((d) => d?.id !== selectedIdToDelete),
    });
  };

  const getCategoryName = (categoryId: string) => {
    return state?.category?.find((x) => x.id === categoryId)?.name;
  };

  const onEdit = (id: string) => {
    handleMode("EDIT", id);
  };

  const showDialogBox = (id: string) => {
    setSelectedIdToDelete(id);
    setIsDialogOpen(true);
  };

  // Builds a parent category -> subcategory -> items tree for the "Category wise" view.
  const createCategoryWiseData = (items: IItems[]) => {
    const categoryById = buildCategoryById(state?.category || []);
    const nodesByCategoryId: Record<string, any> = {};
    const rootNodes: any[] = [];

    const getOrCreateCategoryNode = (categoryId: string) => {
      if (nodesByCategoryId[categoryId]) return nodesByCategoryId[categoryId];

      const cat = categoryById.get(categoryId);
      const node = {
        name: cat?.name || "Uncategorized",
        category: categoryId,
        price: 0,
        children: [] as any[],
      };
      nodesByCategoryId[categoryId] = node;

      if (cat?.parentId) {
        getOrCreateCategoryNode(cat.parentId).children.push(node);
      } else {
        rootNodes.push(node);
      }
      return node;
    };

    items.forEach((item) => {
      getOrCreateCategoryNode(item.category).children.push(item);
    });

    // Roll leaf item prices up through subcategory -> parent category totals.
    const sumPrice = (node: any): number => {
      const total = node.children.reduce((sum: number, child: any) => {
        return (
          sum +
          (child.children
            ? sumPrice(child)
            : parseFloat(String(child.price) || "0"))
        );
      }, 0);
      node.price = total;
      return total;
    };
    rootNodes.forEach(sumPrice);

    // The Tree component from @manish774/smarty-ui doesn't call a column's
    // `render` callback for anything past the first column — it just displays
    // `rowData[column.id]` verbatim. So the export control has to be baked in
    // as an actual data field (matching the "export" column id below) rather
    // than rendered on the fly.
    Object.values(nodesByCategoryId).forEach((node) => {
      node.export = <CategoryExportButton node={node} categoryById={categoryById} />;
    });

    return rootNodes;
  };

  const columnsToBeShown = [
    {
      name: "Name",
      id: "name",
      render: (row) => <span className="item-name-cell">{row.name}</span>,
      highLight: { bgColor: tokens.violet, color: tokens.onAccent },
      searchable: true,
      sortable: true,
    },
    {
      name: "Category",
      id: "category",
      render: (row) => (
        <span
          className="category-chip"
          style={{
            backgroundColor: `${getCategoryColor(row.category)}26`,
            color: getCategoryColor(row.category),
          }}
        >
          <span
            className="category-color-dot"
            style={{ backgroundColor: getCategoryColor(row.category), margin: 0 }}
          />
          {getCategoryName(row.category)}
        </span>
      ),
      highLight: { bgColor: tokens.cyan, color: tokens.onAccent },
      searchable: true,
    },

    {
      name: "Price",
      id: "price",
      sortable: true,
      highLight: { bgColor: tokens.amber, color: tokens.onAccent },
      render: (row) =>
        !isItemsLoading ? (
          <>
            &#8377;
            <Badge type={"bordered"} theme={"warning"} label={row?.price} />
          </>
        ) : (
          ""
        ),
      searchable: true,
    },
    {
      name: "Date",
      id: "date",
      render: (row) => (
        <span className="item-date-cell">
          {isItemsLoading ? "Loading..." : formatDate(row?.date)}
        </span>
      ),
    },
    {
      name: "description",
      id: "description",
      searchable: true,
      render: (row) => <DescriptionCell text={row.description} />,
    },
    {
      name: "Payment mode",
      id: "pmode",
      searchable: true,
    },
    {
      name: "Receipt",
      id: "imageUrl",
      render: (row) =>
        row.imageUrl ? (
          <button
            type="button"
            className="receipt-thumb-btn"
            aria-label="View receipt photo"
            onClick={(e) => {
              e.preventDefault();
              setPreviewImageUrl(row.imageUrl);
            }}
          >
            <img src={row.imageUrl} alt="Receipt thumbnail" />
          </button>
        ) : (
          <ImageNotSupportedRoundedIcon className="receipt-thumb-empty" fontSize="small" />
        ),
    },
    {
      name: "",
      id: "",
      render: (row) => (
        <EditIcon
          className="row-action-icon"
          onClick={(e) => {
            e.preventDefault();
            row.id && onEdit(row?.id);
          }}
        />
      ),
    },
    {
      name: "",
      id: "",
      render: (row) => (
        <button
          className="row-action-btn"
          onClick={(e) => {
            e.preventDefault();
            rowToDeleteRef.current = (e.currentTarget as HTMLElement).closest(
              "tr"
            );
            showDialogBox(row.id);
          }}
        >
          <DeleteIcon className="row-action-icon" />
        </button>
      ),
    },
  ];

  return (
    <div style={{}}>
      <>
        {isItemsLoading ? (
          <Table
            key={themeKey}
            records={[
              {
                name: "",
                category: "",
                price: "",
                date: "Loading...",
                description: "",
              },
            ]}
            config={{
              title: "",
              columns: columnsToBeShown,
            }}
            pageSize={5}
          />
        ) : (
          <Table
            key={themeKey}
            records={state?.items}
            pageSize={5}
            config={{
              filterProps: {
                enable: true,
                columnsToFilter: [
                  {
                    name: "revisit",
                    type: "dropdown",
                    payload: [
                      { name: "Yes", value: "Yes" },
                      { name: "No", value: "No" },
                    ],
                  },
                  {
                    name: "category",
                    type: "dropdown",
                    payload: state?.category?.map((cat) => ({
                      name: cat.name,
                      value: cat.id,
                    })),
                  },
                ],
              },
              title: "Items List",
              paginationRequired: true,
              columns: columnsToBeShown,
              rowHighLight: {
                columnName: "revisit",
                bgColor: "rgb(255, 219, 88)",
                value: "Yes",
              },
            }}
          />
        )}
        {isDialogOpen && (
          <Modal
            isDialogOpen={isDialogOpen}
            component={
              <>
                Are you sure want to delete{" "}
                <h5 style={{ display: "inline" }}>
                  {
                    state?.items?.find((it) => it?.id === selectedIdToDelete)
                      .name
                  }
                </h5>{" "}
                ?
              </>
            }
            dialogSize={"SMALL"}
            onCloseAction={() => {
              setIsDialogOpen(false);
            }}
            submitClick={() => {
              setIsDialogOpen(false);
              const rowEl = rowToDeleteRef.current;
              if (rowEl) {
                // Play the "scrapped paper" animation, then remove the row
                // for real once it's finished crumpling off-screen.
                rowEl.classList.add("row-scrapping");
                window.setTimeout(() => {
                  deleteItem();
                  setSelectedIdToDelete("");
                  rowToDeleteRef.current = null;
                }, ROW_SCRAP_DURATION_MS);
              } else {
                deleteItem();
                setSelectedIdToDelete("");
              }
            }}
          />
        )}
        {!!previewImageUrl && (
          <Modal
            isDialogOpen={!!previewImageUrl}
            component={
              <img
                className="receipt-lightbox-img"
                src={previewImageUrl}
                alt="Receipt full size"
              />
            }
            dialogSize={"MEDIUM"}
            enableFooter={false}
            onCloseAction={() => setPreviewImageUrl("")}
          />
        )}
        <motion.div
          className="total-spend-tile"
          initial={{ opacity: 0, scale: 0.96 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.35, ease: "easeOut" }}
        >
          <span className="total-spend-label">Total spend</span>
          <span className="total-spend-value">
            &#8377;{" "}
            {animatedTotal.toLocaleString("en-IN", {
              maximumFractionDigits: 2,
            })}
          </span>
        </motion.div>
      </>
      <div className="category-wise-tree glass-panel">
        <div className="panel-title-row">
          <h4 className="panel-title">Category wise</h4>
          <button
            type="button"
            className="import-items-btn"
            onClick={() => setIsImportOpen(true)}
          >
            <UploadFileIcon fontSize="small" />
            Import
          </button>
        </div>
        <Tree
          key={themeKey}
          records={categoryData}
          pageSize={10}
          config={{
            title: "Category wise",
            paginationRequired: true,
            columns: [
              {
                name: "Category",
                id: "name",
                render: (row) => (
                  <span
                    className="category-chip"
                    style={{
                      backgroundColor: `${getCategoryColor(row.category)}26`,
                      color: getCategoryColor(row.category),
                    }}
                  >
                    <span
                      className="category-color-dot"
                      style={{
                        backgroundColor: getCategoryColor(row.category),
                        margin: 0,
                      }}
                    />
                    {getCategoryName(row.category)}
                  </span>
                ),
                highLight: { bgColor: tokens.cyan, color: tokens.onAccent },
                searchable: true,
              },
              {
                name: "Price",
                id: "price",
                sortable: true,
                render: (row) => <>₹ {row.price}</>,
                highLight: { bgColor: tokens.amber, color: tokens.onAccent },
                searchable: true,
              },
              {
                // Tree only ever displays rowData[id] for this column — the
                // export button is baked into each node's `export` field in
                // createCategoryWiseData, not rendered here.
                name: "",
                id: "export",
              },
            ],
          }}
        />
      </div>
      {isImportOpen && (
        <Modal
          isDialogOpen={isImportOpen}
          dialogSize={"MEDIUM"}
          enableFooter={false}
          component={<ImportItemsPanel onClose={() => setIsImportOpen(false)} />}
          onCloseAction={() => setIsImportOpen(false)}
        />
      )}
      {/* Analytics charts placed below Category wise data */}
      <div className="analytics-below-tree">
        <Analytics />
      </div>
    </div>
  );
};

export default ItemsList;
