import { SVGProps } from "react";

const Snowflake = ({ cx, cy, r }: { cx: number; cy: number; r: number }) => (
  <g transform={`translate(${cx} ${cy})`} strokeLinecap="round">
    {[0, 60, 120].map((angle) => (
      <line
        key={angle}
        x1={0}
        y1={-r}
        x2={0}
        y2={r}
        transform={`rotate(${angle})`}
      />
    ))}
    {[0, 60, 120].map((angle) => (
      <line
        key={`nub-${angle}`}
        x1={0}
        y1={-r * 0.55}
        x2={r * 0.22}
        y2={-r * 0.78}
        transform={`rotate(${angle})`}
      />
    ))}
  </g>
);

const WinterDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <g stroke="var(--accent-2)" strokeWidth={1.6} opacity={0.9}>
      <Snowflake cx={44} cy={40} r={16} />
    </g>
    <g stroke="var(--accent-1)" strokeWidth={1.4} opacity={0.75}>
      <Snowflake cx={98} cy={72} r={11} />
    </g>
    <g stroke="var(--text-muted)" strokeWidth={1.3} opacity={0.6}>
      <Snowflake cx={64} cy={104} r={8} />
    </g>
    <circle cx={112} cy={30} r={2} fill="var(--accent-2)" opacity={0.7} />
    <circle cx={28} cy={92} r={1.6} fill="var(--accent-1)" opacity={0.6} />
    <circle cx={122} cy={98} r={1.6} fill="var(--text-muted)" opacity={0.5} />
  </svg>
);

export default WinterDoodle;
