import React, { useMemo } from "react";
import { Chart as ChartJS, ArcElement } from "chart.js";
import { Doughnut } from "react-chartjs-2";
import { Box, Typography } from "@mui/material";
import { tokens, fontMono } from "../../../theme";
import { getCategoryColor } from "../../Utils/Utils";
import { IItems, ICategoryProps } from "../../context/DataStateModels";

ChartJS.register(ArcElement);

interface BudgetGaugeRadialProps {
  items: IItems[];
  categories: ICategoryProps[];
}

const BudgetGaugeRadial: React.FC<BudgetGaugeRadialProps> = ({
  items,
  categories,
}) => {
  const { topCategoryId, topCategoryTotal, totalSpend, topShare } =
    useMemo(() => {
      const totals = new Map<string, number>();
      let total = 0;

      items.forEach((item) => {
        const price = parseFloat(item.price as string) || 0;
        const categoryId = item.category || "uncategorized";
        totals.set(categoryId, (totals.get(categoryId) || 0) + price);
        total += price;
      });

      let topId = "";
      let topTotal = 0;
      totals.forEach((value, key) => {
        if (value > topTotal) {
          topTotal = value;
          topId = key;
        }
      });

      return {
        topCategoryId: topId,
        topCategoryTotal: topTotal,
        totalSpend: total,
        topShare: total > 0 ? (topTotal / total) * 100 : 0,
      };
    }, [items]);

  const topCategoryName = useMemo(() => {
    if (!topCategoryId) return "Uncategorized";
    return (
      categories.find((c) => c.id === topCategoryId)?.name || "Uncategorized"
    );
  }, [categories, topCategoryId]);

  const hasData = totalSpend > 0;

  const data = {
    labels: [topCategoryName, "Other"],
    datasets: [
      {
        data: [topCategoryTotal, totalSpend - topCategoryTotal],
        backgroundColor: [
          getCategoryColor(topCategoryId),
          tokens.neutralFill,
        ],
        borderWidth: 0,
      },
    ],
  };

  const options = {
    rotation: -90,
    circumference: 180,
    cutout: "75%",
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false },
    },
  };

  return (
    <>
      <Typography variant="subtitle1">Top Category Share</Typography>
      {hasData ? (
        <Box sx={{ position: "relative", height: 200 }}>
          <Doughnut data={data} options={options} />
          <Box
            sx={{
              position: "absolute",
              left: "50%",
              bottom: "10%",
              transform: "translateX(-50%)",
              textAlign: "center",
              pointerEvents: "none",
            }}
          >
            <Typography
              sx={{
                fontFamily: fontMono,
                fontWeight: 700,
                fontSize: "2rem",
                color: tokens.textPrimary,
                lineHeight: 1,
              }}
            >
              {Math.round(topShare)}%
            </Typography>
            <Typography
              sx={{
                fontSize: "0.75rem",
                color: tokens.textMuted,
                mt: 0.5,
              }}
            >
              {topCategoryName}
            </Typography>
          </Box>
        </Box>
      ) : (
        <Box
          sx={{
            height: 200,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: tokens.textMuted,
          }}
        >
          <Typography variant="body2">No data yet</Typography>
        </Box>
      )}
    </>
  );
};

export default BudgetGaugeRadial;
