import {
  Typography,
  Box,
  Grid,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  SelectChangeEvent,
} from "@mui/material";
import { addDoc, updateDoc } from "firebase/firestore";
import React, { useEffect, useRef, useState } from "react";
import { categoryDoc, categoryList, getCategoryColor } from "../Utils/Utils";
import AddCircleRoundedIcon from "@mui/icons-material/AddCircleRounded";
import SaveRoundedIcon from "@mui/icons-material/SaveRounded";
import { ICategoryProps } from "../context/DataStateModels";
import { useDataStateContext } from "../context/DataStateContext";
import { IItemNCategoryFormProps } from "../Utils/Utils";
import { getDataScopeUserId, getFirebaseServices } from "../../Firebase/config";
import { useFireBase } from "../../context/FirebaseConfigContext";
import "../Items/items.scss";

const CategoryForm = ({
  refresh,
  mode,
  id,
  handleMode,
}: {
  refresh: () => any;
} & IItemNCategoryFormProps) => {
  const { state, dispatch } = useDataStateContext();
  const [category, setCategory] = useState<ICategoryProps>();
  const [isButtonDisable, setIsButtonDisable] = useState(false);
  const [refreshToken, setRefreshToken] = useState<number>(0);
  const { state: firebaseState } = useFireBase();

  const db = getFirebaseServices(firebaseState.userId).db;
  const scopeUserId = getDataScopeUserId(firebaseState.userId);

  const addCategory = async () => {
    if (category?.name) {
      setIsButtonDisable(true);
      try {
        await addDoc(
          categoryList(db),
          scopeUserId ? { ...category, userId: scopeUserId } : category
        );
        category &&
          dispatch({
            type: "addCategory",
            payload: [...state?.category, category],
          });
        setCategory({ name: "" });
        dispatch({ type: "refresh", payload: state?.refreshToken + 1 });
        refresh();
      } catch (e) {
        console.log(e);
      }
      setIsButtonDisable(false);
    }
  };

  const handleCategory = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCategory((prev) => ({
      ...prev,
      name: e?.target.value,
    }));
  };

  const handleParentCategory = (e: SelectChangeEvent) => {
    const value = e?.target.value;
    setCategory((prev) => ({
      ...prev,
      name: prev?.name || "",
      parentId: value ? value : undefined,
    }));
  };

  useEffect(() => {
    if (mode === "EDIT" && id !== "") {
      const { name, parentId } = state?.category?.find(
        (cat) => cat?.id === id
      ) as ICategoryProps;
      setCategory({ name, parentId });
    }
  }, [mode, id, state]);

  const updateCategory = () => {
    if (id && mode === "EDIT") {
      try {
        updateDoc(categoryDoc(id, db), {
          name: category?.name,
          parentId: category?.parentId ?? null,
        });
        const updatedCatagories = state?.category?.map((d) =>
          d?.id === id
            ? {
                ...d,
                name: category?.name,
                parentId: category?.parentId,
                isEdit: false,
              }
            : { ...d }
        );
        dispatch({
          type: "addCategory",
          payload: updatedCatagories,
        });
        handleMode && handleMode("ADD", "");
        setCategory({ name: "" });
      } catch (e) {
        console.log(e);
      }
    }
  };

  const parentCategoryOptions = state?.category?.filter(
    (cat) => !cat?.parentId && cat?.id !== id
  );

  return (
    <div className="item-container">
      <Typography component="h1" variant="h5">
        {mode === "ADD" ? "Add Category" : "Edit Category"}
      </Typography>
      <Box component="form" noValidate sx={{ mt: 3 }}>
        <Grid container spacing={1}>
          <Grid item xs={12} sm={12}>
            <TextField
              autoComplete="given-name"
              name="name"
              required
              fullWidth
              label="category Name"
              value={category?.name}
              id="name"
              onChange={handleCategory}
            />
          </Grid>
          <Grid item xs={12} sm={12}>
            <FormControl fullWidth>
              <InputLabel id="parent-category-select-label">
                Parent Category (optional)
              </InputLabel>
              <Select
                labelId="parent-category-select-label"
                id="parent-category-select"
                value={category?.parentId || ""}
                label="Parent Category (optional)"
                name="parentId"
                onChange={handleParentCategory}
              >
                <MenuItem value="">
                  <em>None</em>
                </MenuItem>
                {parentCategoryOptions?.map((cat) => (
                  <MenuItem key={cat.id} value={cat.id}>
                    <span
                      className="category-color-dot"
                      style={{ backgroundColor: getCategoryColor(cat.id) }}
                    />
                    {cat.name}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Button
            fullWidth
            variant="contained"
            startIcon={
              mode === "ADD" ? (
                <AddCircleRoundedIcon />
              ) : (
                <SaveRoundedIcon />
              )
            }
            sx={{ mt: 3, mb: 2, height: 48 }}
            disabled={isButtonDisable}
            onClick={(e) => {
              e.preventDefault();
              mode === "ADD" ? addCategory() : updateCategory();
            }}
          >
            {mode === "ADD" ? "Add" : "Update"}
          </Button>
        </Grid>
      </Box>
    </div>
  );
};

export default CategoryForm;
