import { useEffect, useState } from "react";
import {
  Box,
  Button,
  Divider,
  IconButton,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import { Modal } from "../Modal";
import {
  hasAdminPassword,
  setAdminPassword,
  verifyAdminPassword,
} from "../../config/adminAuth";
import { AuthSlot } from "../../config/userConfig";

type Step = "checking" | "password-setup" | "password-check" | "form";

interface DeletableUser {
  key: string;
  label: string;
}

interface AddUserDialogProps {
  isOpen: boolean;
  onClose: () => void;
  existingKeys: string[];
  deletableUsers: DeletableUser[];
  onCreate: (key: string, label: string, authSlots: AuthSlot[]) => Promise<void>;
  onDelete: (key: string) => Promise<void>;
}

const slugify = (value: string) =>
  value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");

const AddUserDialog = ({
  isOpen,
  onClose,
  existingKeys,
  deletableUsers,
  onCreate,
  onDelete,
}: AddUserDialogProps) => {
  const [step, setStep] = useState<Step>("checking");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [deletingKey, setDeletingKey] = useState<string | null>(null);
  const [deleteError, setDeleteError] = useState("");

  const [userKey, setUserKey] = useState("");
  const [label, setLabel] = useState("");
  const [slotCount, setSlotCount] = useState(2);
  const [slotValids, setSlotValids] = useState<string[]>(["100", "100"]);

  useEffect(() => {
    if (!isOpen) return;
    setStep("checking");
    setPassword("");
    setConfirmPassword("");
    setError("");
    setUserKey("");
    setLabel("");
    setSlotCount(2);
    setSlotValids(["100", "100"]);
    setDeletingKey(null);
    setDeleteError("");

    hasAdminPassword()
      .then((exists) => setStep(exists ? "password-check" : "password-setup"))
      .catch(() => setError("Couldn't reach the server. Try again."));
  }, [isOpen]);

  const handleSetupPassword = async () => {
    setError("");
    if (password.length < 4) {
      setError("Password must be at least 4 characters.");
      return;
    }
    if (password !== confirmPassword) {
      setError("Passwords don't match.");
      return;
    }
    setBusy(true);
    try {
      await setAdminPassword(password);
      setStep("form");
    } catch {
      setError("Couldn't save the password. Try again.");
    } finally {
      setBusy(false);
    }
  };

  const handleCheckPassword = async () => {
    setError("");
    setBusy(true);
    try {
      const ok = await verifyAdminPassword(password);
      if (!ok) {
        setError("Wrong password.");
        return;
      }
      setStep("form");
    } catch {
      setError("Couldn't reach the server. Try again.");
    } finally {
      setBusy(false);
    }
  };

  const handleSlotCountChange = (count: number) => {
    const bounded = Math.min(4, Math.max(1, count));
    setSlotCount(bounded);
    setSlotValids((prev) => {
      const next = [...prev];
      while (next.length < bounded) next.push("100");
      return next.slice(0, bounded);
    });
  };

  const handleCreateUser = async () => {
    setError("");
    const key = slugify(userKey);
    if (!key) {
      setError("Enter a user id.");
      return;
    }
    if (existingKeys.includes(key)) {
      setError("That user id is already taken.");
      return;
    }
    if (!label.trim()) {
      setError("Enter a display name.");
      return;
    }
    const authSlots: AuthSlot[] = slotValids.map((v) => ({
      defaultValue: 0,
      valid: Math.min(100, Math.max(0, Number(v) || 0)),
    }));

    setBusy(true);
    try {
      await onCreate(key, label.trim(), authSlots);
      onClose();
    } catch {
      setError("Couldn't create the user. Try again.");
    } finally {
      setBusy(false);
    }
  };

  const handleDeleteUser = async (key: string) => {
    setDeleteError("");
    setDeletingKey(key);
    try {
      await onDelete(key);
    } catch {
      setDeleteError("Couldn't delete that user. Try again.");
    } finally {
      setDeletingKey(null);
    }
  };

  const renderStep = () => {
    if (step === "checking") {
      return <Typography>Loading…</Typography>;
    }

    if (step === "password-setup") {
      return (
        <Stack spacing={2} sx={{ minWidth: 280 }}>
          <Typography variant="body2" color="text.secondary">
            No admin password is set yet. Choose one now — only whoever knows
            it will be able to add users after this.
          </Typography>
          <TextField
            label="New admin password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            fullWidth
          />
          <TextField
            label="Confirm password"
            type="password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            fullWidth
          />
          {error && <Typography color="error">{error}</Typography>}
          <Button variant="contained" disabled={busy} onClick={handleSetupPassword}>
            Set password &amp; continue
          </Button>
        </Stack>
      );
    }

    if (step === "password-check") {
      return (
        <Stack spacing={2} sx={{ minWidth: 280 }}>
          <Typography variant="body2" color="text.secondary">
            Enter the admin password to add a user.
          </Typography>
          <TextField
            label="Admin password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleCheckPassword()}
            fullWidth
            autoFocus
          />
          {error && <Typography color="error">{error}</Typography>}
          <Button variant="contained" disabled={busy} onClick={handleCheckPassword}>
            Unlock
          </Button>
        </Stack>
      );
    }

    return (
      <Stack spacing={2} sx={{ minWidth: 280 }}>
        {deletableUsers.length > 0 && (
          <>
            <Typography variant="subtitle2">Users you added</Typography>
            <Stack spacing={0.5}>
              {deletableUsers.map(({ key, label: userLabel }) => (
                <Box
                  key={key}
                  display="flex"
                  alignItems="center"
                  justifyContent="space-between"
                >
                  <Typography variant="body2">{userLabel}</Typography>
                  <IconButton
                    size="small"
                    aria-label={`Delete ${userLabel}`}
                    disabled={deletingKey === key}
                    onClick={() => handleDeleteUser(key)}
                  >
                    <DeleteIcon fontSize="small" />
                  </IconButton>
                </Box>
              ))}
            </Stack>
            {deleteError && <Typography color="error">{deleteError}</Typography>}
            <Divider />
          </>
        )}
        <Typography variant="subtitle2">Add a new user</Typography>
        <TextField
          label="User id"
          helperText="Lowercase, used internally (e.g. rahul)"
          value={userKey}
          onChange={(e) => setUserKey(e.target.value)}
          fullWidth
        />
        <TextField
          label="Display name"
          value={label}
          onChange={(e) => setLabel(e.target.value)}
          fullWidth
        />
        <TextField
          label="Number of pin slots"
          type="number"
          value={slotCount}
          onChange={(e) => handleSlotCountChange(Number(e.target.value))}
          inputProps={{ min: 1, max: 4 }}
          fullWidth
        />
        <Box display="flex" flexDirection="column" gap={1.5}>
          {slotValids.map((value, index) => (
            <TextField
              key={index}
              label={`Slot ${index + 1} correct value (0-100)`}
              type="number"
              value={value}
              onChange={(e) =>
                setSlotValids((prev) =>
                  prev.map((v, i) => (i === index ? e.target.value : v))
                )
              }
              inputProps={{ min: 0, max: 100 }}
              fullWidth
            />
          ))}
        </Box>
        {error && <Typography color="error">{error}</Typography>}
        <Button variant="contained" disabled={busy} onClick={handleCreateUser}>
          Create user
        </Button>
      </Stack>
    );
  };

  return (
    <Modal
      isDialogOpen={isOpen}
      onCloseAction={onClose}
      component={renderStep()}
      dialogSize="SMALL"
      enableFooter={false}
    />
  );
};

export default AddUserDialog;
