import { useCallback, useEffect, useState } from "react";
import { collection, deleteDoc, doc, getDocs, setDoc } from "firebase/firestore";
import { getFirebaseServices } from "../Firebase/config";
import {
  AuthSlot,
  SHARED_PROJECT_KEY,
  UserConfig,
  userConfig as staticUserConfig,
} from "./userConfig";

// Users added from the UI always join the shared project's tenant pool
// (no dedicated `firebase` block), same as a hand-written entry without one.
const APP_USERS_COLLECTION = "AppUsers";

export const useAppUsers = () => {
  const [dynamicUsers, setDynamicUsers] = useState<Record<string, UserConfig>>(
    {}
  );
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const { db } = getFirebaseServices(SHARED_PROJECT_KEY);
        const snapshot = await getDocs(collection(db, APP_USERS_COLLECTION));
        if (cancelled) return;
        const fetched: Record<string, UserConfig> = {};
        snapshot.forEach((docSnap) => {
          const data = docSnap.data() as { label: string; authSlots: AuthSlot[] };
          fetched[docSnap.id] = { label: data.label, authSlots: data.authSlots };
        });
        setDynamicUsers(fetched);
      } catch (e) {
        console.error("Failed to load users from Firebase", e);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const users: Record<string, UserConfig> = {
    ...staticUserConfig,
    ...dynamicUsers,
  };
  const userKeys = Object.keys(users);

  // Only users that exist purely in Firestore (no dedicated `firebase`
  // project) can be removed from here — deleting a dedicated user's entry
  // would strand their pin/label with nowhere left to come from.
  const deletableKeys = Object.keys(dynamicUsers).filter(
    (key) => !staticUserConfig[key]?.firebase
  );

  const addUser = useCallback(
    async (key: string, label: string, authSlots: AuthSlot[]) => {
      const { db } = getFirebaseServices(SHARED_PROJECT_KEY);
      await setDoc(doc(db, APP_USERS_COLLECTION, key), { label, authSlots });
      setDynamicUsers((prev) => ({ ...prev, [key]: { label, authSlots } }));
    },
    []
  );

  const deleteUser = useCallback(async (key: string) => {
    if (staticUserConfig[key]?.firebase) {
      throw new Error("Can't delete a user with a dedicated Firebase project.");
    }
    const { db } = getFirebaseServices(SHARED_PROJECT_KEY);
    await deleteDoc(doc(db, APP_USERS_COLLECTION, key));
    setDynamicUsers((prev) => {
      const next = { ...prev };
      delete next[key];
      return next;
    });
  }, []);

  return { users, userKeys, deletableKeys, addUser, deleteUser, loading };
};
