import { AppBar, Toolbar, Typography, IconButton, Box } from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import ShutdownIcon from "@mui/icons-material/PowerSettingsNew";
import { gradientBrand } from "../theme";
import { useThemeSwitcher } from "../context/ThemeSwitcherContext";
import ThemeSwitcher from "./ThemeSwitcher";
import spidermanMask from "./assets/spiderman-mask.png";

const UserHeader = ({
  userId,
  onLock,
}: {
  userId: string;
  onLock: () => void;
}) => {
  const { themeKey } = useThemeSwitcher();
  const isSpiderman = themeKey === "spiderman";

  return (
    <AppBar position="sticky" elevation={0}>
      <Toolbar variant="dense" sx={{ gap: 1.5 }}>
        <Box
          sx={{
            width: 30,
            height: 30,
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            backgroundImage: isSpiderman ? "none" : gradientBrand,
            overflow: "hidden",
          }}
        >
          {isSpiderman ? (
            <Box
              component="img"
              src={spidermanMask}
              alt=""
              sx={{ width: "100%", height: "100%", objectFit: "cover" }}
            />
          ) : (
            <PersonIcon fontSize="small" htmlColor="#fff" />
          )}
        </Box>
        <Typography
          variant="subtitle1"
          sx={{ textTransform: "capitalize", flexGrow: 1 }}
        >
          {userId}
        </Typography>
        <ThemeSwitcher />
        <IconButton
          onClick={onLock}
          size="small"
          aria-label={`Lock and switch user (currently ${userId})`}
        >
          <ShutdownIcon fontSize="small" />
        </IconButton>
      </Toolbar>
    </AppBar>
  );
};

export default UserHeader;
