import { SVGProps } from "react";

const Kite = ({ cx, cy, s, color, opacity }: { cx: number; cy: number; s: number; color: string; opacity: number }) => (
  <g stroke={color} strokeLinecap="round" strokeLinejoin="round" opacity={opacity}>
    <path d={`M${cx} ${cy - s} L${cx + s} ${cy} L${cx} ${cy + s} L${cx - s} ${cy} Z`} strokeWidth={1.5} />
    <line x1={cx - s} y1={cy} x2={cx + s} y2={cy} strokeWidth={0.9} opacity={0.6} />
    <line x1={cx} y1={cy - s} x2={cx} y2={cy + s} strokeWidth={0.9} opacity={0.6} />
    <path d={`M${cx} ${cy + s} C ${cx - 4} ${cy + s + 10}, ${cx + 4} ${cy + s + 14}, ${cx} ${cy + s + 24}`} strokeWidth={1} opacity={0.55} />
  </g>
);

const KiteDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <Kite cx={50} cy={40} s={16} color="var(--accent-1)" opacity={0.85} />
    <Kite cx={100} cy={70} s={10} color="var(--money)" opacity={0.7} />
    <path
      d="M50 56 C 40 74, 60 88, 44 110"
      stroke="var(--accent-1)"
      strokeWidth={1}
      strokeLinecap="round"
      opacity={0.4}
    />
  </svg>
);

export default KiteDoodle;
