import React, { useState } from "react";
import { IconButton, Menu, MenuItem, Box, Typography } from "@mui/material";
import PaletteRoundedIcon from "@mui/icons-material/PaletteRounded";
import CheckRoundedIcon from "@mui/icons-material/CheckRounded";
import { useThemeSwitcher } from "../context/ThemeSwitcherContext";

const ThemeSwitcher: React.FC = () => {
  const { themeKey, themeList, setThemeKey } = useThemeSwitcher();
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const open = Boolean(anchorEl);

  return (
    <>
      {/* No Tooltip wrapper here — Tooltip adds its own touch listeners on
          top of the button's, and on real touch devices (not reproducible
          via Playwright's synthetic click) that can eat the first tap
          instead of letting it reach onClick. aria-label alone still gives
          screen readers the same label Tooltip would have shown visually. */}
      <IconButton
        onClick={(e) => setAnchorEl(e.currentTarget)}
        aria-label="Switch theme"
        sx={{ width: 44, height: 44 }}
      >
        <PaletteRoundedIcon fontSize="small" />
      </IconButton>
      <Menu
        anchorEl={anchorEl}
        open={open}
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
        transformOrigin={{ vertical: "top", horizontal: "right" }}
      >
        {themeList.map((t) => (
          <MenuItem
            key={t.key}
            selected={t.key === themeKey}
            onClick={() => {
              setThemeKey(t.key);
              setAnchorEl(null);
            }}
            sx={{ gap: 1.5, py: 1.25, minWidth: 260 }}
          >
            <Box sx={{ display: "flex", gap: 0.4 }}>
              {t.swatches.map((c, i) => (
                <Box
                  key={i}
                  sx={{
                    width: 14,
                    height: 14,
                    borderRadius: "50%",
                    backgroundColor: c,
                    border: "1px solid rgba(128,128,128,0.3)",
                  }}
                />
              ))}
            </Box>
            <Box sx={{ display: "flex", flexDirection: "column", flexGrow: 1 }}>
              <Typography variant="body2" sx={{ fontWeight: 600 }}>
                {t.label}
              </Typography>
              <Typography variant="caption" sx={{ opacity: 0.65, lineHeight: 1.3 }}>
                {t.description}
              </Typography>
            </Box>
            {t.key === themeKey && <CheckRoundedIcon fontSize="small" />}
          </MenuItem>
        ))}
      </Menu>
    </>
  );
};

export default ThemeSwitcher;
