import { useMemo } from "react";
import SpiderMaskIcon from "./icons/SpiderMaskIcon";
import SpiderIcon from "./icons/SpiderIcon";

// Same seedable PRNG approach as DoodleField — one Math.random() call seeds
// a deterministic field for the life of this mount.
function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const ICONS = [SpiderMaskIcon, SpiderIcon];
const PALETTE = ["#E62429", "#2E5FE8", "#F2F4F8"];

// Sparser and larger than DoodleField's doodles — a mask or spider reads as
// a "wow" moment, not wallpaper, so a handful scattered across the whole
// scrollable page (not just one viewport) is the right density.
const COUNT = 12;
const COLUMNS = 4;

const SpiderField = () => {
  const items = useMemo(() => {
    const rand = mulberry32(Math.floor(Math.random() * 2 ** 31));
    const rows = Math.ceil(COUNT / COLUMNS);
    const rowSpan = 100 / rows;
    const colSpan = 100 / COLUMNS;

    return Array.from({ length: COUNT }, (_, i) => {
      const Icon = ICONS[Math.floor(rand() * ICONS.length)];
      const col = i % COLUMNS;
      const row = Math.floor(i / COLUMNS);
      const left = col * colSpan + colSpan / 2 + (rand() * colSpan * 0.6 - colSpan * 0.3);
      const top = row * rowSpan + rowSpan / 2 + (rand() * rowSpan * 0.6 - rowSpan * 0.3);
      const size = 64 + rand() * 60;
      const rotate = rand() * 30 - 15;
      const color = PALETTE[Math.floor(rand() * PALETTE.length)];
      const opacity = 0.16 + rand() * 0.16;

      return { key: i, Icon, left, top, size, rotate, color, opacity };
    });
  }, []);

  return (
    <div className="spider-field" aria-hidden="true">
      {items.map(({ key, Icon, left, top, size, rotate, color, opacity }) => (
        <Icon
          key={key}
          className="spider-field-icon"
          style={{
            left: `${left}%`,
            top: `${top}%`,
            width: size,
            height: size,
            color,
            opacity,
            ["--spider-i" as string]: key,
            transform: `translate(-50%, -50%) rotate(${rotate}deg)`,
          }}
        />
      ))}
    </div>
  );
};

export default SpiderField;
